import{_ as t,o as l,c as a,a0 as i}from"./chunks/framework.DYAX5gPL.js";const c=JSON.parse('{"title":"Style Guide","description":"","frontmatter":{"title":"Style Guide"},"headers":[],"relativePath":"en/guide/style/intro.md","filePath":"en/guide/style/intro.md"}'),r={name:"en/guide/style/intro.md"};function n(s,e,d,o,g,y){return l(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="style-overview" tabindex="-1">Style Overview <a class="header-anchor" href="#style-overview" aria-label="Permalink to &quot;Style Overview&quot;">​</a></h1><p>maptalks 3D rendering layers provide a rich styling system for customizing the appearance of 2D or 3D data, including:</p><ul><li>The Symbol style system, which defines how point, line and polygon data is drawn on the map — see the <a href="/en/guide/style/symbols.html">Symbol styles reference</a>.</li><li>The 3D rendering material system, which defines the material style properties of different 3D rendering algorithms — see the <a href="/en/guide/style/material.html">material reference</a>.</li></ul><p>All 3D layers render 3D scenes based on these two styling systems.</p><h2 id="vector-render-plugin-system" tabindex="-1">Vector render plugin system <a class="header-anchor" href="#vector-render-plugin-system" aria-label="Permalink to &quot;Vector render plugin system&quot;">​</a></h2><p>Vector render plugins are the rendering programs inside vector tile layers (<code>VectorTileLayer</code>) and vector layers (<code>PointLayer</code>, <code>LineStringLayer</code>, <code>PolygonLayer</code>).</p><p>The plugin-based design reduces coupling between rendering programs and ensures extensibility and maintainability.</p><p>The current version includes the following render plugins:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Plugin name</th><th style="text-align:left;">Description</th><th>Docs</th></tr></thead><tbody><tr><td style="text-align:left;">icon</td><td style="text-align:left;">Draws icons and text for point, line or polygon data</td><td><a href="/en/guide/style/plugin-icon.html">Docs</a></td></tr><tr><td style="text-align:left;">text</td><td style="text-align:left;">Draws text for point, line or polygon data</td><td><a href="/en/guide/style/plugin-text.html">Docs</a></td></tr><tr><td style="text-align:left;">line</td><td style="text-align:left;">Draws lines or borders for line or polygon data</td><td><a href="/en/guide/style/plugin-line.html">Docs</a></td></tr><tr><td style="text-align:left;">line-gradient</td><td style="text-align:left;">Draws gradient lines for line data</td><td><a href="/en/guide/style/plugin-line-gradient.html">Docs</a></td></tr><tr><td style="text-align:left;">fill</td><td style="text-align:left;">Draws area fills for polygon data</td><td><a href="/en/guide/style/plugin-fill.html">Docs</a></td></tr><tr><td style="text-align:left;">native-line</td><td style="text-align:left;">Draws lines or borders for line or polygon data using native drawing techniques</td><td><a href="/en/guide/style/plugin-native-line.html">Docs</a></td></tr><tr><td style="text-align:left;">native-point</td><td style="text-align:left;">Draws points for point, line or polygon data using native drawing techniques</td><td><a href="/en/guide/style/plugin-native-point.html">Docs</a></td></tr><tr><td style="text-align:left;">lit</td><td style="text-align:left;">Renders 3D polygon data with PBR material</td><td><a href="/en/guide/style/plugin-lit.html">Docs</a></td></tr><tr><td style="text-align:left;">phong</td><td style="text-align:left;">Renders 3D polygon data with Phong material</td><td><a href="/en/guide/style/plugin-phong.html">Docs</a></td></tr><tr><td style="text-align:left;">wireframe</td><td style="text-align:left;">Renders 3D polygon data with a wireframe material</td><td><a href="/en/guide/style/plugin-wireframe.html">Docs</a></td></tr><tr><td style="text-align:left;">gltf-lit</td><td style="text-align:left;">Renders point data with GLTF models using PBR material</td><td><a href="/en/guide/style/plugin-gltf-lit.html">Docs</a></td></tr><tr><td style="text-align:left;">gltf-phong</td><td style="text-align:left;">Renders point data with GLTF models using Phong material</td><td><a href="/en/guide/style/plugin-gltf-phong.html">Docs</a></td></tr><tr><td style="text-align:left;">water</td><td style="text-align:left;">Renders polygon data with a realistic water material</td><td><a href="/en/guide/style/plugin-water.html">Docs</a></td></tr></tbody></table><h2 id="_3d-tiles-layer-styles" tabindex="-1">3D Tiles layer styles <a class="header-anchor" href="#_3d-tiles-layer-styles" aria-label="Permalink to &quot;3D Tiles layer styles&quot;">​</a></h2><p>The styles of 3D Tiles layers are implemented with PBR and Phong materials. You can specify which material is used to render the 3D Tiles models by defining the <code>shader</code> in the <code>service</code> of a <code>Geo3DTilesLayer</code>.</p><p>You can also specify the material rendering parameters by customizing the <code>material</code> property on the <code>service</code>.</p><p>For the specific properties of the <code>material</code> property, see the <a href="/en/guide/style/material.html">material reference</a>.</p><h2 id="visualization-styles" tabindex="-1">Visualization styles <a class="header-anchor" href="#visualization-styles" aria-label="Permalink to &quot;Visualization styles&quot;">​</a></h2><p>To be implemented</p><blockquote><p>This document has been cross-checked against the @maptalks/gl-layers 2026 source code (api-notes-vt-gl.md)</p></blockquote>',16)])])}const p=t(r,[["render",n]]);export{c as __pageData,p as default};
